-- Gata Maula: recarga de insumos desde la hoja Costos Variables del PPTO (con las
-- secciones marcadas: fiambres, quesos, kutsi, cocina, vermut, bebida sin alcohol,
-- panes, packaging), preparaciones (hoja ingredientes) y recetas.
-- Generado automaticamente. Se puede correr aunque ya hayas corrido el 0009: conserva
-- el stock, reemplaza las recetas y borra los insumos que no tienen stock ni movimientos.
-- IMPORTANTE: pisa los precios y los insumos que cargaste desde la app.
begin;
select set_config('app.sin_historial', 'on', true);

delete from public.receta_insumos;
delete from public.recetas;
delete from public.insumos i
 where not exists (select 1 from public.stock s where s.insumo_id = i.id)
   and not exists (select 1 from public.movimientos_stock m where m.insumo_id = i.id)
   and not exists (select 1 from public.desperdicio d where d.insumo_id = i.id)
   and not exists (select 1 from public.ingresos_egresos x where x.insumo_relacionado_id = i.id);

