    ('quesos', 'SANTA OLALLA CAMEMBERT 50G', 'quesos', 'MINI QUESO CAMEMBERT', 'SANTA OLALLA'),
    ('quesos', 'CREMAC SARDO', 'quesos', 'SARDO SOBRERO CREMAC', 'NAPOLES'),
    ('quesos', 'LUCRECIA PROVOLETA', 'quesos', 'PROVOLETA LUCRECIA', 'NAPOLES'),
    ('quesos', 'LA QUESERA GRUYERITO', 'quesos', 'GRUYERE LA QUESERA', null),
    ('quesos', 'VANGUARD AZUL', 'quesos', 'QUESO AZUL BAVARIA', null),
    ('quesos', 'SANTA OLALLA GRUYERE', 'quesos', 'GRUYERE', 'SANTA OLALLA'),
    ('quesos', 'AZUL TORO AZUL', 'quesos', 'AZUL TORO AZUL', 'SANTA OLALLA'),
    ('quesos', 'PATEGRAS lactear', 'quesos', 'PATEGRAS X 4KG', 'COLONIA ORCOVI'),
    ('quesos', 'TYBO GOLACTEOS KUTSI', 'kutsi', 'GOLACTEOS TYBO', null),
    ('quesos', 'MIGUE PROVOLETA', 'quesos', 'PROVOLONE MEDIA HORMA AL VACIO X 1.5KG', 'MIGUE'),
    ('quesos', 'brie LA BOHEME', 'quesos', 'BRIE LA BOHEEM', 'NAPOLES'),
    ('quesos', 'TYBO NOALASA', 'fiambres', 'TYBO NOALSA', 'WAGGON'),
    ('panes', 'Barras', 'panes', 'BARRA DE MASA MADRE', null),
    ('panes', 'Ciabatta', 'panes', 'Pan ciabatta masa madre', null),
    ('panes', 'Focaccia ENTERAS', 'panes', 'FOCACCIA ENTERA', null),
    ('panes', 'Foccacias (cortados/sandwichs)', 'panes', 'focaccia CORTADA', null),
    ('panes', 'Levadura Comun', 'panes', 'PAN BAGUETIN LEVADURA', null),
    ('panes', 'PAN PAPA BURGER', 'kutsi', 'PAN HAMBURGUESA GOLDEN LISO KALIS', 'WAGGON'),
    ('panes', 'PANZ CIABATTA', 'kutsi', 'PAN CIABATTA', 'PANZ'),
    ('panes', 'PANZ PAN A LA CHAPA', 'kutsi', 'PAN A LA CHAPA', null),
    ('panes', 'TORTILLAS MACHOTE', 'cocina', 'WRAP GRANDE', 'MACHOTE')
  ) as v(old_sub, old_name, new_sub, new_nombre, new_marca) loop
    k := public._insumo_id(t.new_sub, t.new_nombre, t.new_marca);
    -- el insumo que tiene el stock: por el nombre de la planilla de stock (primera carga)
    -- o por la descripcion y marca del catalogo (si ya se habia cargado antes)
    select i.id into s from public.insumos i join public.stock st on st.insumo_id = i.id
      where i.id <> k
        and ((i.subcategoria::text = t.old_sub and lower(i.nombre) = lower(t.old_name))
          or (lower(i.nombre) = lower(t.new_nombre) and lower(coalesce(i.marca, '')) = lower(coalesce(t.new_marca, ''))))
      order by st.ultima_actualizacion desc limit 1;
    if k is not null and s is not null and not exists (select 1 from public.stock where insumo_id = k) then
      update public.stock set insumo_id = k where insumo_id = s;
      update public.movimientos_stock set insumo_id = k where insumo_id = s;
      update public.desperdicio set insumo_id = k where insumo_id = s;
      update public.ingresos_egresos set insumo_relacionado_id = k where insumo_relacionado_id = s;
      update public.insumos set proveedor_id = coalesce(proveedor_id, (select proveedor_id from public.insumos where id = s)) where id = k;
      delete from public.insumos where id = s;
      update public.stock set valorizacion = cantidad_actual * (select precio_costo_kg from public.insumos where id = k) where insumo_id = k;
    end if;
  end loop;
end
$$;

